-- Super Admin site configuration: every dropdown list and the editable text
-- of the dashboard and the website, changed without a developer.
--   site_option_lists  one row per dropdown. options = [{value, label, active, min?, max?}]
--                      in display order. A list whose values the backend
--                      validates (extensible = false) can be renamed, hidden and
--                      reordered but never gains or loses a value.
--   site_content       one row per editable text / link / image, with its default.
-- Every change is written to the audit log.

CREATE TABLE IF NOT EXISTS site_option_lists (
  list_key     VARCHAR(80) PRIMARY KEY,
  app          VARCHAR(20) NOT NULL CHECK (app IN ('dashboard', 'website')),
  label        VARCHAR(120) NOT NULL,
  used_in      VARCHAR(200),
  extensible   BOOLEAN NOT NULL DEFAULT TRUE,
  options      JSONB NOT NULL DEFAULT '[]'::jsonb,
  defaults     JSONB NOT NULL DEFAULT '[]'::jsonb,
  updated_by   UUID REFERENCES users(id) ON DELETE SET NULL,
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS site_content (
  content_key   VARCHAR(120) PRIMARY KEY,
  app           VARCHAR(20) NOT NULL CHECK (app IN ('dashboard', 'website')),
  section       VARCHAR(80) NOT NULL,
  label         VARCHAR(160) NOT NULL,
  kind          VARCHAR(20) NOT NULL CHECK (kind IN ('text', 'textarea', 'url', 'email', 'phone', 'image')),
  value         TEXT,
  default_value TEXT NOT NULL DEFAULT '',
  max_length    INT NOT NULL DEFAULT 2000,
  updated_by    UUID REFERENCES users(id) ON DELETE SET NULL,
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);


